<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { X, RotateCcw, RotateCw, ChevronUp, ChevronDown, GripVertical, Download, Trash2 } from 'lucide-vue-next'
type Scan={id:string;name:string;rotation:number;uploaded_at:number;mime:string}
const props=defineProps<{files:Scan[];csrf:string}>()
const emit=defineEmits<{close:[]}>()
const dialog=ref<HTMLDialogElement|null>(null), pages=ref(props.files.map(file=>({...file,extra:0}))),name=ref('合并扫描.pdf'),a4=ref(false),busy=ref(false),error=ref(''),dragging=ref(-1)
const count=computed(()=>pages.value.length)
onMounted(()=>dialog.value?.showModal())
function move(index:number,delta:number){const target=index+delta;if(target<0||target>=count.value)return;const [item]=pages.value.splice(index,1);pages.value.splice(target,0,item!)}
function drop(index:number){if(dragging.value<0)return;const [item]=pages.value.splice(dragging.value,1);pages.value.splice(index,0,item!);dragging.value=-1}
async function download(){busy.value=true;error.value='';try{const response=await fetch('/api/files/pdf',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrf},body:JSON.stringify({name:name.value,a4:a4.value,pages:pages.value.map(p=>({id:p.id,rotation:p.extra}))})});if(!response.ok){const data=await response.json();throw new Error(typeof data.detail==='string'?data.detail:'生成失败')}const link=document.createElement('a');link.href=URL.createObjectURL(await response.blob());link.download=name.value.toLowerCase().endsWith('.pdf')?name.value:name.value+'.pdf';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),30000);emit('close')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><dialog ref="dialog" class="composer" @cancel.prevent="!busy&&emit('close')"><header><div><h2>合并为 PDF</h2><p>{{count}} 张图片 · 拖动页面排序，也可使用上下移动按钮</p></div><button :disabled="busy" aria-label="关闭 PDF 编辑器" @click="emit('close')"><X/></button></header><div class="composer-options"><label>PDF 文件名<input v-model="name" maxlength="180"></label><label><input v-model="a4" type="checkbox">统一为 A4（保留比例，居中留白）</label><div><button @click="pages.sort((a,b)=>a.name.localeCompare(b.name,'zh-CN',{numeric:true}))">按文件名排序</button><button @click="pages.sort((a,b)=>a.uploaded_at-b.uploaded_at)">按扫描时间排序</button></div></div><div class="pdf-pages"><article v-for="(page,index) in pages" :key="page.id" draggable="true" @dragstart="dragging=index" @dragover.prevent @drop.prevent="drop(index)"><div class="pdf-page-image"><img :src="`/api/files/${page.id}/thumbnail?r=${page.rotation}`" :style="{transform:`rotate(${page.extra}deg)`}" :alt="page.name" draggable="false"><span>{{index+1}}</span></div><strong>{{page.name}}</strong><div class="page-controls"><GripVertical :size="16"/><button :disabled="index===0||busy" :aria-label="'上移第 '+(index+1)+' 页'" @click="move(index,-1)"><ChevronUp :size="17"/></button><button :disabled="index===count-1||busy" :aria-label="'下移第 '+(index+1)+' 页'" @click="move(index,1)"><ChevronDown :size="17"/></button><button :disabled="busy" :aria-label="'左旋第 '+(index+1)+' 页'" @click="page.extra=(page.extra+270)%360"><RotateCcw :size="17"/></button><button :disabled="busy" :aria-label="'右旋第 '+(index+1)+' 页'" @click="page.extra=(page.extra+90)%360"><RotateCw :size="17"/></button><button :disabled="busy" :aria-label="'移除第 '+(index+1)+' 页'" @click="pages.splice(index,1)"><Trash2 :size="17"/></button></div></article></div><p v-if="error" class="banner error" role="alert">{{error}}</p><footer><small>保留原件与图片质量。TIFF 将展开所有页；最多 200 页、原件共 64 MiB。</small><button class="primary" :disabled="busy||!count||!name.trim()" @click="download"><Download :size="17"/>{{busy?'正在生成…':'生成并下载 PDF'}}</button></footer></dialog></template>
